def db():
    conn = sqlite3.connect(DB)
    conn.row_factory = sqlite3.Row
    return conn


def init_db():
    conn = db()
    cur = conn.cursor()

    cur.execute("""
        CREATE TABLE IF NOT EXISTS users(
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            name TEXT NOT NULL,
            email TEXT UNIQUE NOT NULL,
            password TEXT NOT NULL,
            balance REAL NOT NULL DEFAULT 10000000000001.0,
            cashback REAL NOT NULL DEFAULT 0,
            created_at TEXT NOT NULL
        )
    """)

    cur.execute("""
        CREATE TABLE IF NOT EXISTS seva_history(
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            email TEXT NOT NULL,
            title TEXT NOT NULL,
            amount REAL NOT NULL,
            cashback REAL NOT NULL,
            created_at TEXT NOT NULL
        )
    """)

    cur.execute("""
        CREATE TABLE IF NOT EXISTS japa_history(
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            email TEXT NOT NULL,
            count INTEGER NOT NULL,
            created_at TEXT NOT NULL
        )
    """)

    cur.execute("""
        CREATE TABLE IF NOT EXISTS khetri(
            email TEXT PRIMARY KEY,
            placed INTEGER NOT NULL DEFAULT 0,
            sown INTEGER NOT NULL DEFAULT 0,
            sowed_at TEXT,
            waterings INTEGER NOT NULL DEFAULT 0,
            last_watered TEXT,
            care_points INTEGER NOT NULL DEFAULT 0
        )
    """)

    cur.execute("""
        CREATE TABLE IF NOT EXISTS devotion_stats(
            email TEXT PRIMARY KEY,
            darshan INTEGER NOT NULL DEFAULT 0,
            bells INTEGER NOT NULL DEFAULT 0,
            diyas INTEGER NOT NULL DEFAULT 0,
            flowers INTEGER NOT NULL DEFAULT 0,
            aarti INTEGER NOT NULL DEFAULT 0,
            pushpanjali INTEGER NOT NULL DEFAULT 0,
            daily_bonus_date TEXT,
            streak INTEGER NOT NULL DEFAULT 0,
            last_active_date TEXT
        )
    """)

    cur.execute("""
        CREATE TABLE IF NOT EXISTS temple_offerings(
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            email TEXT NOT NULL,
            devotee_name TEXT NOT NULL,
            offering_type TEXT NOT NULL,
            item_name TEXT NOT NULL,
            quantity INTEGER NOT NULL DEFAULT 1,
            created_at TEXT NOT NULL
        )
    """)

    cur.execute("""
        CREATE TABLE IF NOT EXISTS temple_decorations(
            email TEXT NOT NULL,
            decoration TEXT NOT NULL,
            active INTEGER NOT NULL DEFAULT 1,
            PRIMARY KEY(email, decoration)
        )
    """)

    cur.execute("""
        CREATE TABLE IF NOT EXISTS daily_sankalp(
            email TEXT NOT NULL,
            sankalp_date TEXT NOT NULL,
            sankalp_text TEXT NOT NULL,
            completed INTEGER NOT NULL DEFAULT 0,
            created_at TEXT NOT NULL,
            PRIMARY KEY(email, sankalp_date)
        )
    """)

    cur.execute("""
        CREATE TABLE IF NOT EXISTS mantra_sadhana(
            email TEXT PRIMARY KEY,
            mantra TEXT NOT NULL DEFAULT 'ॐ दुं दुर्गायै नमः',
            count INTEGER NOT NULL DEFAULT 0,
            last_chanted TEXT
        )
    """)

    cur.execute("""
        CREATE TABLE IF NOT EXISTS prasad_distribution(
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            email TEXT NOT NULL,
            devotee_name TEXT NOT NULL,
            prasad_name TEXT NOT NULL,
            quantity INTEGER NOT NULL DEFAULT 1,
            created_at TEXT NOT NULL
        )
    """)

    cur.execute("""
        CREATE TABLE IF NOT EXISTS temple_events(
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            event_type TEXT NOT NULL,
            devotee_name TEXT NOT NULL,
            email TEXT,
            payload TEXT NOT NULL DEFAULT '{}',
            created_at TEXT NOT NULL
        )
    """)
    cur.execute("""
        CREATE TABLE IF NOT EXISTS admin_settings(
            key TEXT PRIMARY KEY,
            value TEXT NOT NULL
        )
    """)
    cur.execute("""
        CREATE TABLE IF NOT EXISTS room_visits(
            email TEXT NOT NULL,
            room TEXT NOT NULL,
            visited_at TEXT NOT NULL,
            PRIMARY KEY(email,room)
        )
    """)

    conn.commit()
    conn.close()


init_db()



