def is_admin():
    return bool(st.session_state.get("email", "").lower() in ADMIN_EMAILS)

def event_log(event_type, payload=None):
    """Safely record a temple event even if the Streamlit user object is stale/missing."""
    email = str(st.session_state.get("email") or "").strip().lower()
    if not email:
        return

    user = st.session_state.get("user")
    # Streamlit session state can contain None or a stale value after a rerun.
    # Refresh from SQLite before touching user fields so Bhog/Seva never crashes.
    if user is None:
        try:
            user = get_user(email)
            if user is not None:
                st.session_state.user = user
        except Exception:
            user = None

    try:
        if user is not None:
            name = user["name"] if isinstance(user, sqlite3.Row) else user.get("name", "Devotee")
        else:
            name = "Devotee"
    except Exception:
        name = "Devotee"
    name = str(name or "Devotee")

    now = india_now().strftime("%d %b %Y, %I:%M %p")
    conn = db()
    try:
        conn.execute(
            "INSERT INTO temple_events(event_type,devotee_name,email,payload,created_at) VALUES(?,?,?,?,?)",
            (event_type, name, email, json.dumps(payload or {}, ensure_ascii=False), now),
        )
        conn.commit()
    finally:
        conn.close()
    cloud_sync_event(event_type, name, payload or {}, now)

def cloud_sync_event(event_type, devotee_name, payload, created_at):
    """Optional Supabase sync. SQLite remains the offline fallback."""
    if not (SUPABASE_URL and SUPABASE_KEY): return False
    try:
        data=json.dumps({"event_type":event_type,"devotee_name":devotee_name,"payload":payload,"created_at":created_at}).encode()
        req=urllib.request.Request(SUPABASE_URL+"/rest/v1/mandir_events",data=data,headers={"apikey":SUPABASE_KEY,"Authorization":"Bearer "+SUPABASE_KEY,"Content-Type":"application/json","Prefer":"return=minimal"},method="POST")
        with urllib.request.urlopen(req,timeout=3) as r: return 200 <= r.status < 300
    except Exception: return False

def cloud_recent_events(limit=12):
    if not (SUPABASE_URL and SUPABASE_KEY): return []
    try:
        url=SUPABASE_URL+f"/rest/v1/mandir_events?select=event_type,devotee_name,payload,created_at&order=id.desc&limit={int(limit)}"
        req=urllib.request.Request(url,headers={"apikey":SUPABASE_KEY,"Authorization":"Bearer "+SUPABASE_KEY})
        with urllib.request.urlopen(req,timeout=3) as r: return json.loads(r.read().decode())
    except Exception: return []

def record_room_visit(room):
    """Record a room visit without allowing analytics/database issues to block navigation."""
    try:
        conn = db()
        conn.execute("""CREATE TABLE IF NOT EXISTS room_visits(
            email TEXT NOT NULL,
            room TEXT NOT NULL,
            visited_at TEXT NOT NULL,
            PRIMARY KEY(email, room)
        )""")
        conn.execute(
            "INSERT OR REPLACE INTO room_visits(email,room,visited_at) VALUES(?,?,?)",
            (st.session_state.email, room, india_now().isoformat(timespec="seconds"))
        )
        conn.commit()
        conn.close()
    except Exception:
        pass
    try:
        event_log("room_visit", {"room": room})
    except Exception:
        pass

