def devotional_assistant():
    st.markdown("### 🤖 Maa Bhakti Assistant")
    q=st.text_input("Ask about today's Seva, Aarti, Maa, mantra or Navratri",placeholder="Example: What can I offer Maa today?",key="maa_assistant_q")
