def password_hash(password):
    return hashlib.sha256(password.encode("utf-8")).hexdigest()


def get_user(email):
    conn = db()
    row = conn.execute(
        "SELECT * FROM users WHERE email=?",
        (email.lower().strip(),)
    ).fetchone()
    conn.close()
    return row


def register_user(name, email, password):
    conn = db()
    try:
        conn.execute(
            """INSERT INTO users(name,email,password,balance,cashback,created_at)
               VALUES(?,?,?,?,?,?)""",
            (
                name.strip(),
                email.lower().strip(),
                password_hash(password),
                START_BALANCE,
                0,
                india_now().isoformat(timespec="seconds"),
            ),
        )
        conn.execute("INSERT OR IGNORE INTO devotion_stats(email) VALUES(?)", (email.lower().strip(),))
        conn.commit()
        return True, "Account created."
    except sqlite3.IntegrityError:
        return False, "An account with this email already exists."
    finally:
        conn.close()


def login_user(email, password):
    row = get_user(email)
    if row and row["password"] == password_hash(password):
        return row
    return None


def refresh_user():
    """Refresh authenticated user safely after Streamlit reruns."""
    email = str(st.session_state.get("email") or "").strip().lower()
    if not email:
        st.session_state.user = None
        st.session_state.logged_in = False
        return None
    try:
        user = get_user(email)
    except Exception:
        user = None
    st.session_state.user = user
    if user is None:
        st.session_state.logged_in = False
    return user


def seva(title, amount, cashback_percent):
    refresh_user()
    if not st.session_state.get("user"):
        return False, 0

    user = st.session_state.user
    if user["balance"] < amount:
        return False, 0

    cashback = round(amount * cashback_percent / 100, 2)

    conn = db()
    conn.execute(
        "UPDATE users SET balance=balance-?, cashback=cashback+? WHERE email=?",
        (amount, cashback, user["email"])
    )
    conn.execute(
        """INSERT INTO seva_history(email,title,amount,cashback,created_at)
           VALUES(?,?,?,?,?)""",
        (
            user["email"],
            title,
            amount,
            cashback,
            india_now().strftime("%d %b %Y, %I:%M %p"),
        ),
    )
    conn.commit()
    conn.close()

    refresh_user()
    title_lower = title.lower()
    if "diya" in title_lower or "deep" in title_lower:
        bump_stat("diyas")
    if "flower" in title_lower or "pushpa" in title_lower or "mala" in title_lower or "gulab" in title_lower:
        bump_stat("flowers")
    if "pushpanjali" in title_lower:
        bump_stat("pushpanjali")
    return True, cashback


def ensure_stats(email):
    conn = db()
    conn.execute("INSERT OR IGNORE INTO devotion_stats(email) VALUES(?)", (email.lower().strip(),))
    conn.commit()
    row = conn.execute("SELECT * FROM devotion_stats WHERE email=?", (email.lower().strip(),)).fetchone()
    conn.close()
    return row


def bump_stat(field, amount=1):
    allowed = {"darshan", "bells", "diyas", "flowers", "aarti", "pushpanjali"}
    if field not in allowed or not st.session_state.get("email"):
        return
    ensure_stats(st.session_state.email)
    conn = db()
    conn.execute(f"UPDATE devotion_stats SET {field}={field}+? WHERE email=?", (amount, st.session_state.email))
    today = india_now().date().isoformat()
    row = conn.execute("SELECT last_active_date,streak FROM devotion_stats WHERE email=?", (st.session_state.email,)).fetchone()
    streak = row["streak"] or 0
    if row["last_active_date"] != today:
        try:
            from datetime import date, timedelta
            prev = date.fromisoformat(row["last_active_date"]) if row["last_active_date"] else None
            streak = streak + 1 if prev == date.fromisoformat(today) - timedelta(days=1) else 1
        except Exception:
            streak = 1
        conn.execute("UPDATE devotion_stats SET streak=?,last_active_date=? WHERE email=?", (streak,today,st.session_state.email))
    conn.commit()
    conn.close()


def claim_daily_bonus():
    ensure_stats(st.session_state.email)
    today = india_now().date().isoformat()
    conn = db()
    row = conn.execute("SELECT daily_bonus_date FROM devotion_stats WHERE email=?", (st.session_state.email,)).fetchone()
    if row["daily_bonus_date"] == today:
        conn.close()
        return False, 0
    bonus = 108
    conn.execute("UPDATE users SET balance=balance+? WHERE email=?", (bonus, st.session_state.email))
    conn.execute("UPDATE devotion_stats SET daily_bonus_date=? WHERE email=?", (today, st.session_state.email))
    conn.commit(); conn.close()
    refresh_user()
    return True, bonus


def get_devotion_stats():
    return ensure_stats(st.session_state.email)


def achievements_for(stats, seva_count, japa_count, khetri_days):
    checks = [
        ("🌺", "First Darshan", stats["darshan"] >= 1),
        ("🔔", "Temple Bell Sevak", stats["bells"] >= 1),
        ("🪔", "Diya Sevak", stats["diyas"] >= 10),
        ("🌸", "Pushpanjali Sevak", stats["pushpanjali"] >= 5),
        ("📿", "108 Japa", japa_count >= 108),
        ("🌾", "Khetri Sevak", khetri_days >= 3),
        ("🌺", "100 Offerings", seva_count >= 100),
        ("🔥", "7 Day Bhakti Streak", stats["streak"] >= 7),
        ("🙏", "Navratri Sevak", seva_count >= 9),
        ("👑", "Param Bhakti", seva_count >= 250 and japa_count >= 1008),
    ]
    return checks


def record_temple_offering(offering_type, item_name, quantity=1):
    """Record a visible offering in the shared temple activity feed."""
    if not st.session_state.get("email"):
        return
    refresh_user()
    devotee = st.session_state.user["name"] if st.session_state.get("user") else "Devotee"
    conn = db()
    conn.execute(
        """INSERT INTO temple_offerings(email,devotee_name,offering_type,item_name,quantity,created_at)
           VALUES(?,?,?,?,?,?)""",
        (st.session_state.email, devotee, offering_type, item_name, int(quantity),
         india_now().strftime("%d %b %Y, %I:%M %p"))
    )
    conn.commit()
    conn.close()
    event_log("chadhawa", {"offering_type": offering_type, "item_name": item_name, "quantity": int(quantity)})


def temple_offering_summary():
    conn = db()
    total_flowers = conn.execute(
        "SELECT COALESCE(SUM(quantity),0) c FROM temple_offerings WHERE offering_type='Flower'"
    ).fetchone()["c"]
    total_hibiscus = conn.execute(
        "SELECT COALESCE(SUM(quantity),0) c FROM temple_offerings WHERE item_name LIKE '%Hibiscus%'"
    ).fetchone()["c"]
    total_all = conn.execute(
        "SELECT COALESCE(SUM(quantity),0) c FROM temple_offerings"
    ).fetchone()["c"]
    recent = conn.execute(
        """SELECT devotee_name,item_name,quantity,created_at FROM temple_offerings
           ORDER BY id DESC LIMIT 8"""
    ).fetchall()
    conn.close()
    return total_flowers, total_hibiscus, total_all, recent


def youtube_audio_control(youtube_id, button_text, icon="🔔", accent="#d9a441", height=150):
    """Play the user's supplied YouTube recording only after a real click/tap.
    The player is created on the click event so browser autoplay policy is satisfied.
    """
    import html as _html
    safe_button = _html.escape(button_text)
    safe_id = _html.escape(youtube_id, quote=True)
    components.html(f"""
    <div style="font-family:Inter,Arial,sans-serif;text-align:center;padding:4px;">
      <button id="playBtn" aria-label="Play" style="width:92px;height:92px;border:2px solid {accent};border-radius:50%;background:radial-gradient(circle,#fff3c4 0 18%,#d7a33e 20% 48%,#7b0c16 50%);color:#fff7df;font-size:39px;cursor:pointer;box-shadow:0 8px 24px rgba(90,7,16,.35);">{icon}</button>
      <div style="margin-top:9px;color:#7b0c16;font-weight:800;font-size:13px;">{safe_button}</div>
      <div id="player" style="width:1px;height:1px;overflow:hidden;opacity:0;position:absolute;left:-9999px;"></div>
    </div>
    <script>
      const btn=document.getElementById('playBtn');
      const holder=document.getElementById('player');
      btn.addEventListener('click',()=>{{
        holder.innerHTML=`<iframe width="1" height="1" src="https://www.youtube-nocookie.com/embed/{safe_id}?autoplay=1&controls=0&modestbranding=1&playsinline=1&rel=0" title="audio" allow="autoplay; encrypted-media" frameborder="0"></iframe>`;
        btn.style.transform='rotate(-10deg) scale(1.08)';
        setTimeout(()=>btn.style.transform='',220);
      }});
    </script>
    """, height=height, scrolling=False)


def audio_control(title, button_text, audio_url, accent="#d9a441", height=105):
    """Backward-compatible wrapper. For this app, supplied YouTube recordings are used."""
    if youtube_id := (BELL_YOUTUBE_ID if audio_url == BELL_YOUTUBE_ID else None):
        youtube_audio_control(youtube_id, button_text, "🔔", accent, height)
    else:
        youtube_audio_control(DURGA_AARTI_YOUTUBE_ID, button_text, "🪔", accent, height+20)


