DECORATIONS = {
    "🌺 Flower Garland": ("🌺", "A glowing flower garland around Maa"),
    "🪔 Diya Row": ("🪔", "Rows of warm diyas around the mandap"),
    "🏮 Golden Lanterns": ("🏮", "Golden temple lanterns"),
    "🌸 Petal Carpet": ("🌸", "Fresh petals across the temple floor"),
    "🔔 Bell Ornament": ("🔔", "A sacred bell decoration"),
    "🏺 Kalash Pair": ("🏺", "Decorative kalash at the entrance"),
}

def devotee_level(seva_count, japa_count, stats):
    score = int(seva_count)*10 + int(japa_count) + sum(int(stats[k]) for k in ("darshan","diyas","flowers","aarti","pushpanjali"))*2
    levels=[(0,"🌱 New Bhakt"),(100,"🙏 Bhakt"),(300,"🌺 Sevak"),(700,"🪔 Maa Premi"),(1500,"📿 Bhakti Sadhak"),(3000,"👑 Param Bhakt")]
    current=levels[0]
    for threshold,name in levels:
        if score>=threshold: current=(threshold,name)
    nxt=next(((t,n) for t,n in levels if t>score),None)
    return score,current,nxt

def live_temple_stats():
    conn=db()
    devotees=conn.execute("SELECT COUNT(*) c FROM users").fetchone()["c"]
    offerings=conn.execute("SELECT COALESCE(SUM(quantity),0) c FROM temple_offerings").fetchone()["c"]
    flowers=conn.execute("SELECT COALESCE(SUM(quantity),0) c FROM temple_offerings WHERE offering_type='Flower'").fetchone()["c"]
    aarti=conn.execute("SELECT COALESCE(SUM(aarti),0) c FROM devotion_stats").fetchone()["c"]
    japa=conn.execute("SELECT COALESCE(SUM(count),0) c FROM japa_history").fetchone()["c"]
    recent=conn.execute("SELECT devotee_name,item_name,quantity,created_at FROM temple_offerings ORDER BY id DESC LIMIT 6").fetchall()
    conn.close()
    return devotees,offerings,flowers,aarti,japa,recent

def decoration_state():
    conn=db()
    rows=conn.execute("SELECT decoration FROM temple_decorations WHERE email=? AND active=1",(st.session_state.email,)).fetchall()
    conn.close()
    return {r["decoration"] for r in rows}

def toggle_decoration(name):
    conn=db()
    row=conn.execute("SELECT active FROM temple_decorations WHERE email=? AND decoration=?",(st.session_state.email,name)).fetchone()
    if row and row["active"]:
        conn.execute("UPDATE temple_decorations SET active=0 WHERE email=? AND decoration=?",(st.session_state.email,name))
    else:
        conn.execute("INSERT OR REPLACE INTO temple_decorations(email,decoration,active) VALUES(?,?,1)",(st.session_state.email,name))
    conn.commit()
    conn.close()

