def devotional_recommendation(stats):
    if stats["diyas"]<1: return "🪔 Light your first Diya Seva today."
    if stats["flowers"]<11: return "🌺 Offer 11 flowers as today's Pushpa Seva."
    if stats["aarti"]<1: return "🙏 Complete one Aarti for today's devotional practice."
    if stats["pushpanjali"]<1: return "🌸 Offer Pushpanjali before leaving the Mandir."
    return "📿 Continue your Japa and keep your Bhakti streak alive."

