    if not last:
        st.info("Complete a Seva to generate your digital receipt.")
        return
    user=st.session_state.user
    receipt=("HAZRA BARI VIRTUAL DURGA MANDIR 2026\n"
             "====================================\n"
             f"Devotee: {user['name']}\nEmail: {user['email']}\n"
             f"Seva: {last['title']}\nVirtual Amount: {format_money(last['amount'])}\n"
             f"Virtual Cashback: {format_money(last['cashback'])}\nDate: {last['created_at']}\n\n"
             "🙏 Jai Mata Di\nThis receipt records virtual Mandir credits only.\n"
             "It has no cash value and is not a payment receipt.")
    st.download_button("🧾 Download Digital Seva Receipt",receipt,file_name="Hazra_Bari_Seva_Receipt.txt",mime="text/plain",use_container_width=True)
    html=f"""<div class='card' style='border:2px dashed {TODAY_THEME['accent']};text-align:center'><div style='font-size:38px'>🧾</div><h3>Digital Seva Receipt</h3><b>{last['title']}</b><div class='small-muted'>{last['created_at']}</div><div style='margin-top:8px'><b>{format_money(last['amount'])}</b> virtual • <span class='cashback'>+{format_money(last['cashback'])} cashback</span></div><div style='margin-top:8px;color:{TODAY_THEME['deep']};font-weight:900'>🙏 Jai Mata Di</div></div>"""
    st.markdown(html,unsafe_allow_html=True)

