    row = conn.execute("SELECT * FROM daily_sankalp WHERE email=? AND sankalp_date=?", (st.session_state.email, today)).fetchone()
    conn.close()
    st.markdown("### 🕉️ Today's Sankalp")
    if row:
        status = "✅ Sankalp completed today" if row["completed"] else "🙏 Sankalp taken — complete it before leaving the Mandir"
        st.markdown(f"<div class='card' style='text-align:center'><div style='font-size:40px'>🕉️</div><b>{row['sankalp_text']}</b><div class='small-muted' style='margin-top:7px'>{status}</div></div>", unsafe_allow_html=True)
        if not row["completed"] and st.button("✅ Complete Today's Sankalp", key="complete_sankalp", use_container_width=True):
            conn=db(); conn.execute("UPDATE daily_sankalp SET completed=1 WHERE email=? AND sankalp_date=?", (st.session_state.email,today)); conn.commit(); conn.close()
            bump_stat("darshan")
            st.success("🙏 Sankalp completed. Jai Mata Di!"); st.rerun()
