        if st.button("🙏 Take Today's Sankalp", key="take_sankalp", use_container_width=True):
            conn=db(); conn.execute("INSERT INTO daily_sankalp(email,sankalp_date,sankalp_text,created_at) VALUES(?,?,?,?)",(st.session_state.email,today,choice,india_now().strftime("%d %b %Y, %I:%M %p"))); conn.commit(); conn.close()
            st.success("🕉️ Your Sankalp has been recorded."); st.rerun()


