def devotee_leaderboard_feature():
    st.markdown("### 🏆 Mandir Bhakti Leaderboard")
    conn=db()
    users=conn.execute("SELECT email,name FROM users ORDER BY created_at LIMIT 100").fetchall()
    rows=[]
    for u in users:
        stats=conn.execute("SELECT * FROM devotion_stats WHERE email=?",(u['email'],)).fetchone()
        seva=conn.execute("SELECT COUNT(*) c FROM seva_history WHERE email=?",(u['email'],)).fetchone()['c']
        japa=conn.execute("SELECT COALESCE(SUM(count),0) c FROM japa_history WHERE email=?",(u['email'],)).fetchone()['c']
        score=seva*10+japa+((stats['darshan'] if stats else 0)*5)+((stats['aarti'] if stats else 0)*10)+((stats['pushpanjali'] if stats else 0)*8)+((stats['bells'] if stats else 0)*3)
        rows.append((score,u['name'],seva,japa))
    conn.close(); rows.sort(reverse=True,key=lambda x:x[0])
    if not rows: st.info("The leaderboard will appear as devotees join."); return
    for i,(score,name,seva,japa) in enumerate(rows[:10],1):
        medal={1:'🥇',2:'🥈',3:'🥉'}.get(i,'🏅')
        st.markdown(f"<div class='card' style='padding:10px 15px;margin-bottom:6px;display:flex;align-items:center;gap:12px'><div style='font-size:27px'>{medal}</div><div style='flex:1'><b>{name}</b><div class='small-muted'>{seva} Seva • {japa:,} Japa</div></div><b style='color:#7b0c16'>{score:,} pts</b></div>",unsafe_allow_html=True)


