def advanced_devotee_center():
    user = refresh_user()
    if not user:
        st.warning("Please sign in again to open the Advanced Devotee Center.")
        return
    top_header()
    email = user["email"]
    conn = db()
    stats = ensure_stats(email)
    seva_count = conn.execute("SELECT COUNT(*) c FROM seva_history WHERE email=?", (email,)).fetchone()["c"]
    japa_total = conn.execute("SELECT COALESCE(SUM(count),0) c FROM japa_history WHERE email=?", (email,)).fetchone()["c"]
    bhog_total = conn.execute("SELECT COALESCE(SUM(quantity),0) c FROM temple_offerings WHERE email=? AND offering_type='Bhog'", (email,)).fetchone()["c"]
    offering_total = conn.execute("SELECT COALESCE(SUM(quantity),0) c FROM temple_offerings WHERE email=?", (email,)).fetchone()["c"]
    recent = conn.execute("SELECT title,amount,cashback,created_at FROM seva_history WHERE email=? ORDER BY id DESC LIMIT 5", (email,)).fetchall()
    conn.close()
    xp = int(stats["darshan"]*10 + stats["bells"]*2 + stats["diyas"]*3 + stats["flowers"]*2 + stats["aarti"]*12 + stats["pushpanjali"]*5 + seva_count*8 + japa_total//10 + bhog_total*4)
    levels=[(0,"🌱 Bhakt"),(100,"🌺 Sevak"),(300,"🙏 Sadhak"),(700,"🪔 Upasak"),(1500,"🔱 Shakti Bhakt"),(3000,"👑 Maha Sevak")]
    level_name,level_floor=levels[0][1],0
    next_floor=100
    for threshold,name in levels:
        if xp>=threshold: level_name,level_floor=name,threshold
        else: next_floor=threshold; break
    else: next_floor=level_floor+1000
    progress=1.0 if next_floor<=level_floor else min(1.0,max(0.0,(xp-level_floor)/(next_floor-level_floor)))
    st.markdown("<div class='section-title'><h2>🌟 Advanced Devotee Center</h2><span>Your complete Mata Rani journey</span></div>",unsafe_allow_html=True)
    st.markdown(f"<div class='card' style='background:linear-gradient(135deg,#4b0710,#8b1521);color:#fff4d0;border:0;padding:24px'><div style='font-size:13px;letter-spacing:2px;font-weight:800'>DEVOTEE LEVEL</div><div style='font-size:34px;font-weight:900'>{level_name}</div><div style='margin-top:10px;background:#ffffff33;border-radius:999px;height:12px;overflow:hidden'><div style='width:{progress*100:.1f}%;height:100%;background:#f3c85b'></div></div><div style='margin-top:8px'>{xp:,} XP • Next level: {max(0,next_floor-xp):,} XP</div></div>",unsafe_allow_html=True)
    cols=st.columns(6)
    metrics=[("🙏",stats["darshan"],"Darshan"),("🌺",seva_count,"Seva"),("🍬",bhog_total,"Bhog"),("📿",japa_total,"Japa"),("🪔",stats["diyas"],"Diya"),("🔥",stats["streak"],"Streak")]
    for col,(ic,val,label) in zip(cols,metrics):
        with col: st.markdown(f"<div class='stat-card' style='text-align:center'><div style='font-size:26px'>{ic}</div><div class='stat-value'>{val:,}</div><div class='stat-label'>{label}</div></div>",unsafe_allow_html=True)
    st.markdown("### 🎯 Today's Bhakti Missions")
    missions=[("📿","Complete 108 Japa",japa_total % 108 == 0 and japa_total > 0,"japa"),("🪔","Light a Virtual Diya",stats["diyas"] > 0,"diya"),("🙏","Take Maa Darshan",stats["darshan"] > 0,"darshan"),("🌺","Offer One Seva",seva_count > 0,"seva"),("🍬","Offer Maa's Bhog",bhog_total > 0,"puja"),("🕯️","Attend Aarti",stats["aarti"] > 0,"aarti")]
    cols=st.columns(3)
    for i,(ic,title,done,page) in enumerate(missions):
        with cols[i%3]:
            st.markdown(f"<div class='card' style='min-height:125px'><b>{ic} {title}</b><div class='small-muted' style='margin-top:7px'>{'✅ Completed' if done else '⬜ Not completed yet'}</div></div>",unsafe_allow_html=True)
            if not done and st.button(f"Open {title}",key=f"mission_{i}",use_container_width=True): go(page)
    st.markdown("### ⚡ Quick Actions")
    qcols=st.columns(6)
    quick=[("📺 Darshan","darshan"),("🍬 Bhog","puja"),("📿 Japa","japa"),("🪔 Diya","diya"),("🕯️ Aarti","aarti"),("🙏 Sankalp","sankalp")]
    for col,(label,page) in zip(qcols,quick):
        with col:
            if st.button(label,key=f"adv_{page}",use_container_width=True): go(page)
    st.markdown("### 📜 Recent Seva Activity")
    if recent:
        for row in recent: st.markdown(f"<div class='card' style='padding:10px;margin-bottom:6px'><b>{row['title']}</b> • {format_money(row['amount'])}<span class='small-muted'> • {row['created_at']}</span><br><span class='cashback'>Cashback {format_money(row['cashback'])}</span></div>",unsafe_allow_html=True)
    else: st.info("Your Seva activity will appear here.")
    st.markdown("### 🏆 Milestones")
    achievements=achievements_for(stats,seva_count,japa_total,0)
    acols=st.columns(5)
    for i,(ic,name,ok) in enumerate(achievements):
        with acols[i%5]: st.markdown(f"<div class='card' style='text-align:center;opacity:{1 if ok else .45};min-height:110px'><div style='font-size:30px'>{ic}</div><b>{name}</b><div class='small-muted'>{'Unlocked ✓' if ok else 'Locked'}</div></div>",unsafe_allow_html=True)
    st.markdown("### 📊 Personal Temple Analytics")
    ac1,ac2,ac3=st.columns(3)
    with ac1: st.metric("Total offerings",f"{offering_total:,}")
    with ac2: st.metric("Total Japa",f"{japa_total:,}")
    with ac3: st.metric("Current streak",f"{stats['streak']} days")

