DRIK_PANCHANG_URL = "https://www.drikpanchang.com/panchang/day-panchang.html?geoname-id=1272175"
DRIK_MONTH_URL = "https://www.drikpanchang.com/panchang/month-panchang.html?geoname-id=1272175"
TEMPLE_LOCATION_FULL = "Sagarbhanga, Durgapur-11, Paschim Bardhaman, West Bengal - 713211, India"

class _ShaktiTextExtractor(HTMLParser):
    def __init__(self):
        super().__init__()
        self.parts=[]
    def handle_data(self, data):
        if data and data.strip():
            self.parts.append(data.strip())
    def text(self):
        return " ".join(self.parts)

def _shakti_dp_text(html):
    parser=_ShaktiTextExtractor()
    parser.feed(html)
    return re.sub(r"\s+", " ", parser.text()).strip()

def _shakti_dp_clean(value):
    return re.sub(r"\s+", " ", str(value or "")).strip(" -:,")

def _shakti_dp_page_section(text):
    """Keep only the useful Drik day-page text and never expose site navigation/catalog text."""
    marker="Online Day Panchang for Durgapur, West Bengal, India"
    pos=text.find(marker)
    if pos >= 0:
        text=text[pos:]
    # The actual day data begins at the Ashwina/Paksha line in the fetched page.
    # Drop the long navigation/header material before that point.
    m=re.search(r"\b(?:[0-9]{1,2}),\s*Ashwina\s+Krishna\b", text, re.I)
    if m:
        text=text[m.start():]
    return text

def _shakti_dp_value(text, label, next_labels):
    stop="|".join(re.escape(x) for x in next_labels)
    m=re.search(rf"\b{re.escape(label)}\b\s*[:\-]?\s*(.*?)\s*(?={stop}|$)", text, re.I)
    return _shakti_dp_clean(m.group(1)) if m else "—"

def fetch_shakti_panchang():
    try:
        req=urllib.request.Request(DRIK_PANCHANG_URL, headers={"User-Agent":"Mozilla/5.0"})
        with urllib.request.urlopen(req, timeout=12) as r:
            html=r.read().decode("utf-8", "ignore")
        text=_shakti_dp_page_section(_shakti_dp_text(html))

        # Restrict extraction to the actual day-page body. This prevents Drik's
        # navigation catalog (Calendars, Muhurat, Jyotish, etc.) from appearing
        # inside the Nakshatra/Tithi cards when page separators are missing.
        vals={
            "Tithi": "—",
            "Nakshatra": "—",
            "Paksha": "—",
            "Sunrise": "—",
            "Sunset": "—",
            "Moonrise": "—",
            "Moonset": "—",
        }

        # Extract only the four astronomical times requested by the Mandir UI.
        for field in ("Sunrise", "Sunset", "Moonrise", "Moonset"):
            m=re.search(rf"\b{field}\b\s+([0-9]{{1,2}}:[0-9]{{2}}\s*[AP]M)", text, re.I)
            if m:
                vals[field]=_shakti_dp_clean(m.group(1))

        # Paksha appears in the day summary; never expose Yoga or Karana.
        m=re.search(r"Paksha\s*[:\-]?\s*([A-Za-z]+(?:\s+Paksha)?)", text, re.I)
        if m: vals["Paksha"]=_shakti_dp_clean(m.group(1))

        # Prefer the compact day-summary values and ignore menu/navigation matches.
        # Tithi examples: Ekadashi, Ekadashi upto 12:34 AM, Oct 07.
        tithi_names=(
            "Pratipada","Dwitiya","Tritiya","Chaturthi","Panchami","Shashthi",
            "Saptami","Ashtami","Navami","Dashami","Ekadashi","Dwadashi",
            "Trayodashi","Chaturdashi","Purnima","Amavasya"
        )
        tpat=r"(?:"+"|".join(tithi_names)+r")"
        m=re.search(rf"({tpat})(?:\s+upto\s+([0-9]{{1,2}}:[0-9]{{2}}\s*[AP]M(?:\s*,\s*[A-Za-z]+\s+[0-9]{{1,2}})?))?", text, re.I)
        if m:
            vals["Tithi"]=_shakti_dp_clean(m.group(1) + (" upto " + m.group(2) if m.group(2) else ""))

        # Nakshatra is extracted from the actual day body only. If Drik changes
        # its separators, stop at the next known astronomical field.
        nak_names=(
            "Ashwini","Bharani","Krittika","Rohini","Mrigashira","Ardra",
            "Punarvasu","Pushya","Ashlesha","Magha","Purva Phalguni",
            "Uttara Phalguni","Hasta","Chitra","Swati","Vishakha",
            "Anuradha","Jyeshtha","Mula","Purva Ashadha","Uttara Ashadha",
            "Shravana","Dhanishtha","Shatabhisha","Purva Bhadrapada",
            "Uttara Bhadrapada","Revati"
        )
        npat=r"(?:"+"|".join(re.escape(x) for x in nak_names)+r")"
        m=re.search(rf"({npat})(?:\s+upto\s+([0-9]{{1,2}}:[0-9]{{2}}\s*[AP]M(?:\s*,\s*[A-Za-z]+\s+[0-9]{{1,2}})?))?", text, re.I)
        if m:
            vals["Nakshatra"]=_shakti_dp_clean(m.group(1) + (" upto " + m.group(2) if m.group(2) else ""))

        return {**vals,"ok":True,"updated":india_now().strftime("%d %b %Y, %I:%M %p IST")}
    except Exception as exc:
        return {"ok":False,"Tithi":"—","Nakshatra":"—","Paksha":"—","Sunrise":"—","Sunset":"—","Moonrise":"—","Moonset":"—","error":str(exc)}

def shakti_panchang_strip():
    d=fetch_shakti_panchang()
    st.markdown("<div class='section-title'><h2>🌅 Today's Panchang</h2><span>Drik Panchang • Durgapur calculation • Yoga/Karana hidden</span></div>",unsafe_allow_html=True)
    a,b=st.columns(2)
    with a:
        st.metric("🌙 Tithi",d["Tithi"])
        st.metric("⭐ Nakshatra",d["Nakshatra"])
    with b:
        st.metric("☀️ Sunrise",d["Sunrise"])
        st.metric("🌇 Sunset",d["Sunset"])
    c,e=st.columns(2)
    with c: st.metric("🌙 Moonrise",d["Moonrise"])
    with e: st.metric("🌙 Moonset",d["Moonset"])
    st.markdown(f"<div class='card'><b>🌗 Paksha:</b> {d['Paksha']}<br><span class='small-muted'>Calculation: Durgapur, West Bengal • Temple: {TEMPLE_LOCATION_FULL}</span></div>",unsafe_allow_html=True)

