def persistent_altar(total_hibiscus, total_flowers):
    total_hibiscus = int(total_hibiscus or 0)
    visible = min(total_hibiscus, 108)
    flowers = "".join(f"<span class=\"altar-flower\">🌺</span>" for _ in range(visible))
    extra = max(0, total_hibiscus - visible)
    st.markdown(f"""
    <div class="card" style="text-align:center;padding:18px;background:linear-gradient(145deg,#fff8e9,#fffdf7);border:2px solid #d8a53e;">
      <div style="font-size:12px;font-weight:900;letter-spacing:2px;color:#7b0c16;">🛕 MAA'S VIRTUAL OFFERING ALTAR</div>
      <div style="font-size:66px;margin:8px 0;">🙏</div>
      <div style="display:flex;flex-wrap:wrap;justify-content:center;gap:3px;max-width:760px;margin:auto;">{flowers or '<span style="font-size:15px;color:#806d62;">Your first offering will appear here.</span>'}</div>
      <div style="margin-top:12px;font-weight:900;color:#7b0c16;">🌺 {total_hibiscus} hibiscus at the altar</div>
      {f'<div class="small-muted">+ {extra} more hibiscus are recorded in the Mandir total</div>' if extra else ''}
      <div class="small-muted" style="margin-top:5px">Other Chadhawa offerings are also recorded in the Live Temple Seva below.</div>
    </div>
    <style>
      .altar-flower{{font-size:27px;display:inline-block;animation:altarPulse 1.8s ease-in-out infinite alternate;}}
      @keyframes altarPulse{{from{{transform:translateY(0) scale(.96)}}to{{transform:translateY(-3px) scale(1.04)}}}}
    </style>
    """, unsafe_allow_html=True)


