def ensure_khetri(email):
    conn = db()
    conn.execute("INSERT OR IGNORE INTO khetri(email) VALUES(?)", (email,))
    conn.commit()
    row = conn.execute("SELECT * FROM khetri WHERE email=?", (email,)).fetchone()
    conn.close()
    return row


def update_khetri(**values):
    email = st.session_state.email
    conn = db()
    sets = ", ".join(f"{k}=?" for k in values)
    params = list(values.values()) + [email]
    conn.execute(f"UPDATE khetri SET {sets} WHERE email=?", params)
    conn.commit()
    conn.close()


def khetri_growth():
    row = ensure_khetri(st.session_state.email)
    if not row["sown"] or not row["sowed_at"]:
        return row, 0.0, 0, "Not yet sown"
    try:
        sowed = datetime.fromisoformat(row["sowed_at"])
        days_float = max(0, (india_now() - sowed).total_seconds() / 86400)
    except Exception:
        days_float = 0
    height = min(18.0, days_float * 2.0 + min(row["care_points"], 20) * 0.05)
    if height < 0.5:
        stage = "Seeds resting in the soil"
    elif height < 2.5:
        stage = "Tiny sprouts"
    elif height < 6:
        stage = "Fresh green shoots"
    elif height < 12:
        stage = "Growing Khetri"
    else:
        stage = "Tall, healthy barley"
    return row, height, int(days_float), stage


def draw_khetri(height_cm, planted=False):
    if not planted:
        sprouts = ""
    else:
        blade_count = max(5, min(18, int(5 + height_cm)))
        sprouts = "".join(
            f'<span class="blade" style="height:{max(12, int(height_cm*5 + (i%4)*5))}px;transform:rotate({-28 + i*3}deg);left:{28 + (i*37)%145}px"></span>'
            for i in range(blade_count)
        )
    return f'''<div class="khetri-scene">
      <div class="khetri-halo">ॐ</div>
      <div class="khetri-kalash">
        <div class="kalash-mouth"></div><div class="kalash-neck"></div><div class="kalash-body"></div>
        <div class="kalash-tilak">Shri</div>
      </div>
      <div class="khetri-soil"><div class="seed-row"></div>{sprouts}</div>
      <div class="khetri-floor"></div>
    </div>'''


def kalash():
    top_header()
    row, height, days, stage = khetri_growth()
    planted = bool(row["sown"])
    placed = bool(row["placed"])

    st.markdown(f'''<div class="section-title"><h2>🌾 Kalash & Khetri</h2>
    <span>Place the sacred Kalash • sow barley • care for your Khetri • watch it grow</span></div>''', unsafe_allow_html=True)

    growth_text = f"Growth: {height:.1f} cm • Day {days}" if planted else "Your sacred Khetri is ready to begin."
    st.markdown(f'''<div class="card" style="text-align:center;padding:14px;background:linear-gradient(180deg,{TODAY_THEME['soft']},{PHASE_SURFACE}) !important;border-color:{TODAY_THEME['accent']} !important">
      <div style="font-size:12px;font-weight:800;letter-spacing:1px;color:{TODAY_THEME['deep']}">VIRTUAL KHETRI</div>
      <div style="font-size:26px;font-family:Georgia,serif;margin-top:4px">{stage}</div>
      <div class="small-muted">{growth_text}</div>
    </div>''', unsafe_allow_html=True)

    st.markdown(draw_khetri(height, planted), unsafe_allow_html=True)

    a,b,c = st.columns(3)
    with a:
        if st.button("🏺 Place Kalash", use_container_width=True, disabled=placed):
            update_khetri(placed=1)
            st.success("🏺 The sacred Kalash has been placed.")
            st.rerun()
        if placed:
            st.caption("Kalash placed in your virtual Mandir.")
    with b:
        if st.button("🌾 Sow Barley Seeds", use_container_width=True, disabled=not placed or planted):
            update_khetri(sown=1, sowed_at=india_now().isoformat(timespec="seconds"), care_points=1)
            st.success("🌾 Barley seeds have been lovingly sown.")
            st.rerun()
    with c:
        if st.button("💧 Water Khetri", use_container_width=True, disabled=not planted):
            update_khetri(waterings=row["waterings"] + 1, last_watered=india_now().isoformat(timespec="seconds"), care_points=row["care_points"] + 1)
            st.success("💧 Khetri cared for with water.")
            st.rerun()

    d,e,f = st.columns(3)
    with d:
        if st.button("☀️ Give Sunlight", use_container_width=True, disabled=not planted):
            update_khetri(care_points=row["care_points"] + 1)
            st.success("☀️ A little sunlight has been given to the Khetri.")
            st.rerun()
    with e:
        if st.button("🙏 Offer Care", use_container_width=True, disabled=not planted):
            update_khetri(care_points=row["care_points"] + 1)
            st.success("🙏 Your Khetri has received loving care.")
            st.rerun()
    with f:
        if planted:
            last = row["last_watered"] or "Not watered yet"
            st.markdown(f'''<div class="stat-card"><div class="stat-value">{height:.1f} cm</div><div class="stat-label">Estimated barley height</div><div class="small-muted">Watered {row['waterings']} time(s)<br>Last care: {last}</div></div>''', unsafe_allow_html=True)

    progress = min(100, height / 18 * 100)
    st.markdown(f'''<div class="card" style="margin-top:18px">
      <h3>🌱 Khetri Growth</h3>
      <p class="small-muted">Your virtual barley grows with time after sowing. Caring for it adds a little extra growth.</p>
      <div style="height:18px;border-radius:999px;background:#ddd8c7;overflow:hidden;margin:12px 0">
        <div style="height:100%;width:{progress:.1f}%;background:linear-gradient(90deg,#6f8f45,#2f6f4e);border-radius:999px"></div>
      </div>
      <div style="display:flex;justify-content:space-between;font-weight:700"><span>🌱 Seeds</span><span>🌿 18 cm</span></div>
    </div>''', unsafe_allow_html=True)

    if st.button("← Home", key="back_kalash"):
        go("home")

