                st.caption(f"{qty} × {icon} = {format_money(amount)} virtual Mandir money")
                if st.button(f"{icon} Offer {qty} to Maa", type="primary", use_container_width=True, key="bhog_offer_"+safe_key):
                    ok, cashback = seva(title, amount, cb)
                    if ok:
                        record_temple_offering("Bhog", title, int(qty))
                        st.session_state.last_chadhawa_qty = int(qty)
                        st.session_state.last_chadhawa_flower = icon
                        st.session_state.last_chadhawa_name = title
                        st.session_state.chadhawa_just_offered = True
                        st.session_state.toast = f"{qty} × {title} offered to Maa. Virtual cashback: {format_money(cashback)}."
                        st.rerun()
                    else:
                        st.error("Your virtual Mandir balance is not sufficient.")


