def _dual_safe_user_name():
    try:
        u = st.session_state.get("user")
        if u is None:
            refresh_user()
            u = st.session_state.get("user")
        return str(u["name"] if isinstance(u, sqlite3.Row) else (u or {}).get("name", "Devotee"))
    except Exception:
        return "Devotee"

# Keep the original image function name so every existing page automatically
# receives the selected temple's deity image.
def show_maa_image(width=None):
    """Render the currently selected temple deity. Shiva always uses lord_shiva.png."""
    try:
        if temple_is_shiva():
            # Never fall back to Maa Durga artwork inside Shiva Mandir.
            if os.path.isfile(SHIVA_IMAGE):
                with open(SHIVA_IMAGE, "rb") as f:
                    img64 = base64.b64encode(f.read()).decode("utf-8")
            else:
                # Never fall back to Maa Durga artwork. Use the embedded Shiva image.
                img64 = SHIVA_IMAGE_B64
            st.markdown(
                f"""<div class=\"maa-stage shiva-stage\">
                  <img src=\"data:image/png;base64,{img64}\" class=\"maa-img shiva-img\" alt=\"Lord Shiva • Mahadev\" />
                  <div class=\"maa-glow\" style=\"box-shadow:0 0 55px 18px {TODAY_THEME['accent']}55;\"></div>
                </div>""",
                unsafe_allow_html=True,
            )
            return
        path = MAA_IMAGE
        if os.path.isfile(path):
            with open(path, "rb") as f:
                img64 = base64.b64encode(f.read()).decode("utf-8")
        else:
            img64 = MAA_IMAGE_B64
        dress = TODAY_THEME["deep"] if THEME_PHASE == "Dark" else TODAY_THEME["primary"]
        st.markdown(
            f"""<div class=\"maa-stage\">
              <img src=\"data:image/png;base64,{img64}\" class=\"maa-img\" alt=\"Maa Durga\" />
              <div class=\"maa-dress-tint\" style=\"background:{dress};\"></div>
              <div class=\"maa-glow\" style=\"box-shadow:0 0 55px 18px {TODAY_THEME['accent']}55;\"></div>
            </div>""",
            unsafe_allow_html=True,
        )
    except Exception as exc:
        st.error(f"Unable to display the selected deity image: {exc}")

def dual_migrate_db():
    # Add a temple marker without disturbing any existing data.
    try:
        conn = db()
        for table in ("seva_history", "japa_history", "temple_offerings"):
            cols = [r["name"] for r in conn.execute(f"PRAGMA table_info({table})").fetchall()]
            if "temple" not in cols:
                conn.execute(f"ALTER TABLE {table} ADD COLUMN temple TEXT NOT NULL DEFAULT 'maa'")
        conn.commit()
        conn.close()
    except Exception:
        pass

dual_migrate_db()

def dual_record_temple_offering(offering_type, item_name, quantity=1):
    if not st.session_state.get("email"):
        return
    refresh_user()
    devotee = _dual_safe_user_name()
    conn = db()
    try:
        conn.execute(
            """INSERT INTO temple_offerings(email,devotee_name,offering_type,item_name,quantity,created_at,temple)
               VALUES(?,?,?,?,?,?,?)""",
            (st.session_state.email, devotee, offering_type, item_name, int(quantity),
             india_now().strftime("%d %b %Y, %I:%M %p"), "shiva" if temple_is_shiva() else "maa")
        )
        conn.commit()
    finally:
        conn.close()
    try:
        event_log("shiva_offering" if temple_is_shiva() else "chadhawa",
                  {"temple": "shiva" if temple_is_shiva() else "maa",
                   "offering_type": offering_type, "item_name": item_name, "quantity": int(quantity)})
    except Exception:
        pass

record_temple_offering = dual_record_temple_offering

def dual_seva(title, amount, cashback_percent):
    refresh_user()
    user = st.session_state.get("user")
    if not user:
        return False, 0
    if float(user["balance"]) < amount:
        return False, 0
    cashback = round(amount * cashback_percent / 100, 2)
    temple = "shiva" if temple_is_shiva() else "maa"
    conn = db()
    try:
        conn.execute("UPDATE users SET balance=balance-?, cashback=cashback+? WHERE email=?",
                     (amount, cashback, user["email"]))
        cols = [r["name"] for r in conn.execute("PRAGMA table_info(seva_history)").fetchall()]
        if "temple" in cols:
            conn.execute(
                "INSERT INTO seva_history(email,title,amount,cashback,created_at,temple) VALUES(?,?,?,?,?,?)",
                (user["email"], title, amount, cashback,
                 india_now().strftime("%d %b %Y, %I:%M %p"), temple)
            )
        else:
            conn.execute(
                "INSERT INTO seva_history(email,title,amount,cashback,created_at) VALUES(?,?,?,?,?)",
                (user["email"], title, amount, cashback,
                 india_now().strftime("%d %b %Y, %I:%M %p"))
            )
        conn.commit()
    finally:
        conn.close()
    refresh_user()
    return True, cashback

seva = dual_seva

