def dual_temple_offering_summary():
    temple = "shiva" if temple_is_shiva() else "maa"
    conn = db()
    try:
        row1 = conn.execute("SELECT COALESCE(SUM(quantity),0) c FROM temple_offerings WHERE offering_type='Flower' AND temple=?", (temple,)).fetchone()
        row2 = conn.execute("SELECT COALESCE(SUM(quantity),0) c FROM temple_offerings WHERE item_name LIKE '%Hibiscus%' AND temple=?", (temple,)).fetchone()
        row3 = conn.execute("SELECT COALESCE(SUM(quantity),0) c FROM temple_offerings WHERE temple=?", (temple,)).fetchone()
        recent = conn.execute("""SELECT devotee_name,item_name,quantity,created_at FROM temple_offerings
                                 WHERE temple=? ORDER BY id DESC LIMIT 8""",(temple,)).fetchall()
        return int(row1["c"]), int(row2["c"]), int(row3["c"]), recent
    except Exception:
        # Fallback for an older DB before migration.
        rows = conn.execute("""SELECT devotee_name,item_name,quantity,created_at FROM temple_offerings
                               ORDER BY id DESC LIMIT 8""").fetchall()
        total = conn.execute("SELECT COALESCE(SUM(quantity),0) c FROM temple_offerings").fetchone()["c"]
        conn.close()
        return 0,0,int(total),rows
    finally:
        try: conn.close()
        except Exception: pass

temple_offering_summary = dual_temple_offering_summary

