        row = items[start:start+3]
        cols = st.columns(3)
        for col, item in zip(cols, row):
            icon, title, desc, unit_price, cb, max_qty, unit_label = item
            with col:
                st.markdown(
                    f"""<div class="card service-card" style="min-height:215px"><div class="service-icon">{icon}</div><h3>{title}</h3><p>{desc}</p><div><span class="price">{format_money(unit_price)}</span> / {unit_label}&nbsp; <span class="cashback">{cb}% Cashback</span></div></div>""",
                    unsafe_allow_html=True,
                )
                safe_key = ''.join(ch if ch.isalnum() else '_' for ch in title)
                prefix = "shiva_" if temple_is_shiva() else "maa_"
                qty = st.number_input(f"Quantity ({unit_label})", min_value=1, max_value=max_qty, value=1, step=1, key=prefix+"bhog_qty_"+safe_key)
                amount = int(qty) * int(unit_price)
                st.caption(f"{qty} × {icon} = {format_money(amount)} virtual Mandir money")
                if st.button(f"{icon} Offer {qty} to {deity}", type="primary", use_container_width=True, key=prefix+"bhog_offer_"+safe_key):
                    ok, cashback = seva(title, amount, cb)
