    with m2: st.markdown(f"<div class='stat-card' style='text-align:center'><div style='font-size:28px'>🌸</div><div class='stat-value'>{total_flowers}</div><div class='stat-label'>Flower offerings</div></div>", unsafe_allow_html=True)
    with m3: st.markdown(f"<div class='stat-card' style='text-align:center'><div style='font-size:28px'>🙏</div><div class='stat-value'>{total_all}</div><div class='stat-label'>Total Seva units</div></div>", unsafe_allow_html=True)
    if not temple_is_shiva():
        persistent_altar(total_hibiscus, total_flowers)
    all_offering_altar()
    if st.session_state.get("chadhawa_just_offered"):
        qty_anim = st.session_state.get("last_chadhawa_qty", 1)
        icon_anim = st.session_state.get("last_chadhawa_flower", "🙏")
        name_anim = st.session_state.get("last_chadhawa_name", "Seva")
        chadhawa_animation(qty_anim, icon_anim, name_anim)
        st.success(f"🙏 Offering complete — {qty_anim} × {name_anim} reached the virtual altar.")
        if st.button("✓ Close Offering View", use_container_width=True, key="close_offer_view_dual"):
            st.session_state.chadhawa_just_offered = False
            st.rerun()
    bhog_section()
    st.markdown(f"<div class='section-title'><h2>🛕 {'Choose Mahadev Seva' if temple_is_shiva() else 'Choose Your Chadhawa'}</h2><span>Quantity + virtual price + cashback + live altar recording</span></div>",unsafe_allow_html=True)
    for start in range(0, len(items), 3):
        row = items[start:start+3]
        cols = st.columns(3)
        for col,item in zip(cols,row):
            icon,title,desc,unit_price,cb,max_qty,unit_label=item
            with col:
                st.markdown(f"""<div class="card service-card" style="min-height:220px"><div class="service-icon">{icon}</div><h3>{title}</h3><p>{desc}</p><div><span class="price">{format_money(unit_price)}</span> / {unit_label}&nbsp; <span class="cashback">{cb}% Cashback</span></div></div>""",unsafe_allow_html=True)
                safe=''.join(ch if ch.isalnum() else '_' for ch in title)
                prefix="shiva_" if temple_is_shiva() else "maa_"
                qty=st.number_input(f"Quantity ({unit_label})",min_value=1,max_value=max_qty,value=1,step=1,key=prefix+"seva_qty_"+safe)
                amount=int(qty)*int(unit_price)
                st.caption(f"{qty} × {icon} = {format_money(amount)} virtual Mandir money")
                if st.button(f"{icon} Offer {qty} to {deity}",type="primary",use_container_width=True,key=prefix+"seva_offer_"+safe):
                    ok,cashback=seva(title,amount,cb)
                    if ok:
                        offering_type="Flower" if any(x in title for x in ("Flower","Hibiscus","Gulab","Bilva Patra","Aak")) else "Seva"
                        record_temple_offering(offering_type,title,int(qty))
                        if offering_type=="Flower":
                            bump_stat("flowers",int(qty))
                        st.session_state.last_chadhawa_qty=int(qty)
                        st.session_state.last_chadhawa_flower=icon
                        st.session_state.last_chadhawa_name=title
                        st.session_state.chadhawa_just_offered=True
                        st.session_state.toast=f"{qty} × {title} offered to {deity}. Virtual cashback: {format_money(cashback)}."
                        st.rerun()
                    else: st.error("Your virtual Mandir balance is not sufficient.")
    if st.session_state.toast:
        st.success("🙏 "+st.session_state.toast); st.session_state.toast=""
    st.markdown(f"<div class='section-title'><h2>👀 Live {deity} Seva</h2><span>Recent offerings are visible to devotees using this Mandir server</span></div>",unsafe_allow_html=True)
    if recent:
        for r in recent:
            st.markdown(f"<div class='card' style='padding:12px;margin-bottom:8px'><b>🙏 {r['devotee_name']}</b> offered <b>{r['quantity']} × {r['item_name']}</b><div class='small-muted'>{r['created_at']}</div></div>",unsafe_allow_html=True)
    else:
        st.info(f"🌺 The first offering will appear here for {deity}.")
    if st.button("← Back to Mandir",key="back_seva_dual"): go("home")

