def dual_top_header():
    # Several legacy feature pages call top_header() internally. The dual-temple
    # wrappers also call it, so make the header idempotent within one Streamlit run.
    # This prevents StreamlitDuplicateElementKey errors such as top_switch_temple.
    if st.session_state.get("_dual_header_rendered", False):
        return
    st.session_state["_dual_header_rendered"] = True
    user = refresh_user() if st.session_state.get("logged_in") else None
    c1,c2,c3,c4=st.columns([2.25,1.25,1.0,0.9])
    with c1:
        st.markdown(
            f"<div style='font-family:DM Serif Display;font-size:25px;color:#5a0710'>{temple_icon()} Hazra Bari {temple_short_name()} Mandir</div>"
            f"<div class='small-muted'>Virtual Darshan • Seva • Bhog • Aarti • Japa</div>",
            unsafe_allow_html=True)
    with c2:
        st.markdown(f"<div style='margin-top:6px;display:inline-block;padding:5px 10px;border-radius:999px;background:{TODAY_THEME['soft']};border:1px solid {TODAY_THEME['accent']};color:{TODAY_THEME['deep']};font-size:11px;font-weight:800'>Today's Theme • {TODAY_THEME['name']} • {THEME_PHASE}</div>",unsafe_allow_html=True)
    with c3:
        if st.button("🔄 Switch",key="top_switch_temple",use_container_width=True):
            st.session_state.page="temple_select"; st.rerun()
    with c4:
        if user is not None and st.button("👤 Account",key="top_account_dual",use_container_width=True):
            go("account")
    st.markdown(f"<div class='card' style='padding:8px 12px;margin:4px 0 12px;text-align:center'><b>{temple_greeting()}</b> • Current temple: <b>{temple_name()}</b></div>",unsafe_allow_html=True)

