def dual_login_screen():
    st.markdown("<div class='login-shell'>", unsafe_allow_html=True)
    st.markdown("""<div class="login-brand"><div class="om">ॐ</div><h1>Hazra Bari Virtual Mandir</h1><div class="small-muted">Darshan • Seva • Bhog • Aarti • Japa • Bhakti</div></div>""",unsafe_allow_html=True)
    left,right=st.columns([1,1.05])
    with left:
        st.markdown("<div class='card' style='padding:12px'>",unsafe_allow_html=True)
        # Login is neutral/Maa-branded; the selected temple image is shown after temple selection. This prevents Shiva artwork from appearing before a temple is chosen.
        old=st.session_state.get("temple","maa"); st.session_state.temple="maa"
        show_maa_image()
        st.session_state.temple=old
        st.markdown("</div>",unsafe_allow_html=True)
    with right:
        st.markdown("<div class='card'>",unsafe_allow_html=True)
        a,b=st.columns(2)
        with a:
            if st.button("Sign In",use_container_width=True,type="primary" if st.session_state.login_mode=="login" else "secondary"):
                st.session_state.login_mode="login"; st.rerun()
        with b:
            if st.button("Create Account",use_container_width=True,type="primary" if st.session_state.login_mode=="register" else "secondary"):
                st.session_state.login_mode="register"; st.rerun()
        if st.session_state.login_mode=="login":
            st.markdown("### Welcome back 🙏")
            email=st.text_input("Email",key="login_email")
            password=st.text_input("Password",type="password",key="login_password")
            if st.button("ENTER MANDIR",type="primary",use_container_width=True,key="dual_enter"):
                user=login_user(email,password)
                if user:
                    st.session_state.logged_in=True
                    st.session_state.email=user["email"]
                    st.session_state.user=user
                    st.session_state.page="temple_select"
                    st.session_state.temple="maa"
                    st.rerun()
                else: st.error("Email or password is incorrect.")
        else:
            st.markdown("### Begin your Mandir journey 🌺")
            name=st.text_input("Your Name",key="reg_name")
            email=st.text_input("Email",key="reg_email")
            password=st.text_input("Create Password",type="password",key="reg_password")
            confirm=st.text_input("Confirm Password",type="password",key="reg_confirm")
            if st.button("CREATE MY MANDIR ACCOUNT",type="primary",use_container_width=True,key="dual_register"):
                if not name.strip() or not email.strip() or not password: st.warning("Please complete all fields.")
                elif password!=confirm: st.warning("Passwords do not match.")
                elif len(password)<6: st.warning("Please use at least 6 characters.")
                else:
                    ok,message=register_user(name,email,password)
                    if ok:
                        st.success("Account created. You can now enter the Mandir.")
                        st.session_state.login_mode="login"
                    else: st.error(message)
        st.markdown("<div class='virtual-note'>All wallet and Seva amounts are virtual Mandir credits only. No real-money payment is processed.</div>",unsafe_allow_html=True)
        st.markdown("</div>",unsafe_allow_html=True)
    st.markdown("</div>",unsafe_allow_html=True)

