def dual_aarti_thali(active=False):
    """Functional Aarti Thali for both temples.

    Uses native Streamlit controls so the thali remains visible and usable even if
    custom HTML/CSS is blocked or partially rendered by the browser.
    """
    shiva = temple_is_shiva()
    deity = "Baba Mahadev" if shiva else "Maa Durga"

    common_items = [
        ("🪔", "Diya", "Light the sacred lamp"),
        ("🔴", "Kumkum", "Sacred vermilion"),
        ("🌾", "Akshat", "Unbroken rice grains"),
        ("🌺", "Flowers", "Fresh devotional flowers"),
        ("🕯️", "Dhup", "Incense for the Aarti"),
        ("✨", "Camphor", "Camphor flame"),
        ("🍬", "Prasad", "Sweet prasad offering"),
        ("💧", "Jal", "Sacred water"),
        ("🔔", "Ghanti", "Temple bell"),
        ("🟠", "Roli", "Sacred roli"),
    ]
    deity_items = [
        ("🌿", "Bilva", "Sacred Bilva leaves for Mahadev"),
        ("🕉️", "Bhasma", "Sacred Vibhuti/Bhasma for Mahadev"),
    ] if shiva else [
        ("🌺", "Red Hibiscus", "Maa Durga flower offering"),
        ("👘", "Chunri", "Maa Durga Chunri seva"),
    ]
    items = common_items + deity_items

    # Native visual header — no dependency on the fragile custom thali HTML.
    st.markdown(
        f"""
        <div style="padding:16px;border-radius:20px;border:2px solid {TODAY_THEME['accent']};background:linear-gradient(135deg,{TODAY_THEME['soft']},#fffdf7);text-align:center;">
          <div style="font-size:52px;">{'🔱 🪔 🌿 🕉️' if shiva else '🌺 🪔 🔔 🌺'}</div>
          <div style="font-size:18px;font-weight:900;color:{TODAY_THEME['deep']};">🪔 AARTI THALI • {deity.upper()} PUJA ESSENTIALS</div>
          <div style="margin-top:6px;color:{TODAY_THEME['deep']};">Complete functional Aarti-thali feature with common and deity-specific sacred items.</div>
        </div>
        """,
        unsafe_allow_html=True,
    )

    # IMPORTANT: Streamlit widget state must be changed BEFORE the keyed checkboxes
    # are instantiated in the current run. Otherwise Streamlit raises
    # StreamlitWidgetAlreadyInstantiatedError when "Select Complete Thali" is clicked.
    temple_key = "shiva" if shiva else "maa"
    if st.button("✓ Select Complete Thali", use_container_width=True, key=f"aarti_select_all_{temple_key}"):
        for icon, name, desc in items:
            safe = "".join(ch if ch.isalnum() else "_" for ch in name.lower())
            st.session_state[f"aarti_thali_{temple_key}_{safe}"] = True
        st.rerun()

    # A compact visual thali that does not rely on absolute-positioned HTML.
    st.markdown("### 🪔 Thali Contents")
    cols = st.columns(3)
    for idx, (icon, name, desc) in enumerate(items):
        safe = "".join(ch if ch.isalnum() else "_" for ch in name.lower())
        key = f"aarti_thali_{temple_key}_{safe}"
        if key not in st.session_state:
            st.session_state[key] = True
        with cols[idx % 3]:
            st.checkbox(f"{icon} {name}", key=key, help=desc)

    selected = []
    for icon, name, desc in items:
        safe = "".join(ch if ch.isalnum() else "_" for ch in name.lower())
        key = f"aarti_thali_{temple_key}_{safe}"
        if st.session_state.get(key, True):
            selected.append(name)

    c1, c2, c3 = st.columns(3)
    with c1:
        st.metric("Items selected", f"{len(selected)}/{len(items)}")
    with c2:
        price = 301 if shiva else 251
        st.metric("Virtual Seva", format_money(price))
    with c3:
        st.metric("Cashback", "10%")

    if selected:
        st.success(f"🪔 Ready to offer: {', '.join(selected)}")
    else:
        st.warning("Select at least one Aarti item before offering the thali.")

    if not active:
        if st.button(
            f"🙏 BEGIN AARTI — OFFER THALI TO {('MAHADEV' if shiva else 'MAA')}",
            type="primary", use_container_width=True,
            key=f"begin_aarti_{'shiva' if shiva else 'maa'}"
        ):
            if not selected:
                st.error("Please select at least one Aarti item first.")
            else:
                st.session_state.aarti_active = True
                bump_stat("aarti")
                st.rerun()
    else:
        st.success(f"🪔 Aarti is in progress before {deity}. Move the virtual thali with devotion.")
        if st.button(
            f"✓ COMPLETE AARTI & OFFER THE THALI TO {('MAHADEV' if shiva else 'MAA')}",
            type="primary", use_container_width=True,
            key=f"complete_aarti_{'shiva' if shiva else 'maa'}"
        ):
            price = 301 if shiva else 251
            ok, cashback = seva("Complete Aarti Thali", price, 10)
            if ok:
                record_temple_offering("Aarti", "Complete Aarti Thali", 1)
                st.session_state.aarti_active = False
                st.session_state.aarti_receipt = {
                    "deity": deity,
                    "items": list(selected),
                    "amount": price,
                    "cashback": cashback,
                }
                st.rerun()
            else:
                st.error("Your virtual Mandir balance is not sufficient.")

    receipt = st.session_state.get("aarti_receipt")
    if receipt and receipt.get("deity") == deity:
        st.success(
            f"🙏 Aarti Thali offered successfully to {deity}. "
            f"Virtual Seva: {format_money(receipt['amount'])} • "
            f"Cashback: {format_money(receipt['cashback'])}"
        )
        st.caption("Items offered: " + ", ".join(receipt["items"]))
        if st.button("✓ Close Aarti Receipt", use_container_width=True, key=f"close_aarti_receipt_{'shiva' if shiva else 'maa'}"):
            st.session_state.aarti_receipt = None
            st.rerun()

aarti_thali = dual_aarti_thali

