def sankalp_feature():
    today=india_now().date().isoformat()
    conn=db(); row=conn.execute("SELECT * FROM daily_sankalp WHERE email=? AND sankalp_date=?",(st.session_state.email,today)).fetchone(); conn.close()
    deity=_dual_deity_word()
    if temple_is_shiva():
        options=["I will perform one sincere Seva for Mahadev today.","I will chant Om Namah Shivaya with devotion today.","I will offer Aarti to Mahadev today.","I will care for my Khetri today.","I will begin the day with gratitude to Mahadev."]
    else:
        options=["I will perform one sincere Seva for Maa Durga today.","I will chant Maa Durga's mantra with devotion today.","I will offer Aarti to Maa Durga today.","I will care for my Khetri today.","I will begin the day with gratitude to Maa Durga."]
    st.markdown(f"### 🕉️ Today's Sankalp • {deity}")
    if row:
        status="✅ Sankalp completed today" if row["completed"] else "🙏 Sankalp taken — complete it before leaving the Mandir"
        st.markdown(f"<div class='card' style='text-align:center'><div style='font-size:40px'>🕉️</div><b>{row['sankalp_text']}</b><div class='small-muted' style='margin-top:7px'>{status}</div></div>",unsafe_allow_html=True)
        if not row["completed"] and st.button("✅ Complete Today's Sankalp",key="complete_sankalp",use_container_width=True):
            conn=db(); conn.execute("UPDATE daily_sankalp SET completed=1 WHERE email=? AND sankalp_date=?",(st.session_state.email,today)); conn.commit(); conn.close(); bump_stat("darshan"); st.success(f"🙏 Sankalp completed. {temple_greeting()}"); st.rerun()
    else:
        choice=st.selectbox("Choose your Sankalp",options,key="sankalp_choice")
        if st.button("🙏 Take Today's Sankalp",key="take_sankalp",use_container_width=True):
            conn=db(); conn.execute("INSERT INTO daily_sankalp(email,sankalp_date,sankalp_text,created_at) VALUES(?,?,?,?)",(st.session_state.email,today,choice,india_now().strftime('%d %b %Y, %I:%M %p'))); conn.commit(); conn.close(); st.success("🕉️ Your Sankalp has been recorded."); st.rerun()

def mantra_sadhana_feature():
    deity=_dual_deity_word(); mantra=temple_mantra(); icon="🔱" if temple_is_shiva() else "🌺"
    conn=db(); conn.execute("INSERT OR IGNORE INTO mantra_sadhana(email) VALUES(?)",(st.session_state.email,)); conn.commit(); row=conn.execute("SELECT * FROM mantra_sadhana WHERE email=?",(st.session_state.email,)).fetchone(); conn.close()
    st.markdown(f"### 📿 Mantra Sadhana • {deity}")
    st.markdown(f"<div class='card' style='text-align:center;background:linear-gradient(145deg,#fff8e7,#fffdf8)'><div style='font-size:34px'>{icon}</div><div style='font-size:23px;font-weight:900;color:{TODAY_THEME['deep']}'>{mantra}</div><div class='small-muted'>Chant count: <b>{row['count']:,}</b></div></div>",unsafe_allow_html=True)
    cols=st.columns(3)
    with cols[0]:
        if st.button("📿 +1 Japa",key="mantra_plus",use_container_width=True):
            conn=db(); conn.execute("UPDATE mantra_sadhana SET count=count+1,last_chanted=? WHERE email=?",(india_now().isoformat(timespec='seconds'),st.session_state.email)); conn.commit(); conn.close(); st.rerun()
    with cols[1]:
        if st.button("📿 +108 Japa",key="mantra_108",use_container_width=True):
            conn=db(); conn.execute("UPDATE mantra_sadhana SET count=count+108,last_chanted=? WHERE email=?",(india_now().isoformat(timespec='seconds'),st.session_state.email)); conn.commit(); conn.close(); st.toast("🙏 One Mala completed!"); st.rerun()
    with cols[2]:
        if st.button("🪷 108 Reset View",key="mantra_view",use_container_width=True): st.session_state.mantra_view=0
    count=int(row['count']); cycle=count%108
    st.progress(cycle/108 if cycle else 0,text=f"Mala progress: {cycle}/108 beads")
    if cycle==0 and count>0: st.success(f"🪷 Mala complete — {deity}'s blessings be with you.")

