def advanced_devotee_center():
    user=refresh_user()
    if not user: st.warning("Please sign in again to open the Advanced Devotee Center."); return
    top_header(); email=user["email"]; conn=db(); stats=ensure_stats(email)
    seva_count=conn.execute("SELECT COUNT(*) c FROM seva_history WHERE email=?",(email,)).fetchone()["c"]
    japa_total=conn.execute("SELECT COALESCE(SUM(count),0) c FROM japa_history WHERE email=?",(email,)).fetchone()["c"]
    bhog_total=conn.execute("SELECT COALESCE(SUM(quantity),0) c FROM temple_offerings WHERE email=? AND offering_type='Bhog'",(email,)).fetchone()["c"]
    offering_total=conn.execute("SELECT COALESCE(SUM(quantity),0) c FROM temple_offerings WHERE email=?",(email,)).fetchone()["c"]
    recent=conn.execute("SELECT title,amount,cashback,created_at FROM seva_history WHERE email=? ORDER BY id DESC LIMIT 5",(email,)).fetchall(); conn.close()
    xp=int(stats["darshan"]*10+stats["bells"]*2+stats["diyas"]*3+stats["flowers"]*2+stats["aarti"]*12+stats["pushpanjali"]*5+seva_count*8+japa_total//10+bhog_total*4)
    if temple_is_shiva(): levels=[(0,"🌱 Bhakt"),(100,"🌿 Sevak"),(300,"🙏 Sadhak"),(700,"🪔 Upasak"),(1500,"🔱 Mahadev Bhakt"),(3000,"👑 Maha Sevak")]
    else: levels=[(0,"🌱 Bhakt"),(100,"🌺 Sevak"),(300,"🙏 Sadhak"),(700,"🪔 Upasak"),(1500,"🌺 Shakti Bhakt"),(3000,"👑 Maha Sevak")]
    level_name,level_floor=levels[0][1],0; next_floor=100
    for threshold,name in levels:
        if xp>=threshold: level_name,level_floor=name,threshold
        else: next_floor=threshold; break
    else: next_floor=level_floor+1000
    progress=1.0 if next_floor<=level_floor else min(1.0,max(0.0,(xp-level_floor)/(next_floor-level_floor)))
    deity=_dual_deity_word()
    st.markdown(f"<div class='section-title'><h2>🌟 Advanced Devotee Center</h2><span>Your complete {deity} journey</span></div>",unsafe_allow_html=True)
    st.markdown(f"<div class='card' style='background:linear-gradient(135deg,#4b0710,#8b1521);color:#fff4d0;border:0;padding:24px'><div style='font-size:13px;letter-spacing:2px;font-weight:800'>DEVOTEE LEVEL</div><div style='font-size:34px;font-weight:900'>{level_name}</div><div style='margin-top:10px;background:#ffffff33;border-radius:999px;height:12px;overflow:hidden'><div style='width:{progress*100:.1f}%;height:100%;background:#f3c85b'></div></div><div style='margin-top:8px'>{xp:,} XP • Next level: {max(0,next_floor-xp):,} XP</div></div>",unsafe_allow_html=True)
    cols=st.columns(6); metrics=[("🙏",stats["darshan"],"Darshan"),("🌿" if temple_is_shiva() else "🌺",seva_count,"Seva"),("🍬",bhog_total,"Bhog"),("📿",japa_total,"Japa"),("🪔",stats["diyas"],"Diya"),("🔥",stats["streak"],"Streak")]
    for col,(ic,val,label) in zip(cols,metrics):
        with col: st.markdown(f"<div class='stat-card' style='text-align:center'><div style='font-size:26px'>{ic}</div><div class='stat-value'>{val:,}</div><div class='stat-label'>{label}</div></div>",unsafe_allow_html=True)
    st.markdown("### 🎯 Today's Bhakti Missions")
    missions=[("📿","Complete 108 Japa",japa_total%108==0 and japa_total>0,"japa"),("🪔","Light a Virtual Diya",stats["diyas"]>0,"diya"),("🙏",f"Take {deity} Darshan",stats["darshan"]>0,"darshan"),("🌿" if temple_is_shiva() else "🌺","Offer One Seva",seva_count>0,"seva"),("🍬",f"Offer {deity}'s Bhog",bhog_total>0,"puja"),("🕯️","Attend Aarti",stats["aarti"]>0,"aarti")]
    cols=st.columns(3)
    for i,(ic,title,done,page) in enumerate(missions):
        with cols[i%3]:
            st.markdown(f"<div class='card' style='min-height:125px'><b>{ic} {title}</b><div class='small-muted' style='margin-top:7px'>{'✅ Completed' if done else '⬜ Not completed yet'}</div></div>",unsafe_allow_html=True)
            if not done and st.button(f"Open {title}",key=f"mission_{i}",use_container_width=True): go(page)
    st.markdown("### ⚡ Quick Actions")
    qcols=st.columns(6)
    for col,(label,page) in zip(qcols,[("📺 Darshan","darshan"),("🍬 Bhog","puja"),("📿 Japa","japa"),("🪔 Diya","diya"),("🕯️ Aarti","aarti"),("🙏 Sankalp","sankalp")]):
        with col:
            if st.button(label,key=f"adv_{page}",use_container_width=True): go(page)
    st.markdown("### 📜 Recent Seva Activity")
    if recent:
        for row in recent: st.markdown(f"<div class='card' style='padding:10px;margin-bottom:6px'><b>{row['title']}</b> • {format_money(row['amount'])}<span class='small-muted'> • {row['created_at']}</span><br><span class='cashback'>Cashback {format_money(row['cashback'])}</span></div>",unsafe_allow_html=True)
    else: st.info("Your Seva activity will appear here.")
    st.markdown("### 🏆 Milestones")
    achievements=achievements_for(stats,seva_count,japa_total,0); acols=st.columns(5)
    for i,(ic,name,ok) in enumerate(achievements):
        with acols[i%5]: st.markdown(f"<div class='card' style='text-align:center;opacity:{1 if ok else .45};min-height:110px'><div style='font-size:30px'>{ic}</div><b>{name}</b><div class='small-muted'>{'Unlocked ✓' if ok else 'Locked'}</div></div>",unsafe_allow_html=True)
    st.markdown("### 📊 Personal Temple Analytics")
    ac1,ac2,ac3=st.columns(3)
    with ac1: st.metric("Total offerings",f"{offering_total:,}")
    with ac2: st.metric("Total Japa",f"{japa_total:,}")
    with ac3: st.metric("Current streak",f"{stats['streak']} days")

def dashboard():
    top_header(); refresh_user(); user=st.session_state.user; stats=get_devotion_stats(); conn=db()
    temple="shiva" if temple_is_shiva() else "maa"
    try:
        seva_count=conn.execute("SELECT COUNT(*) c FROM seva_history WHERE email=? AND temple=?",(user["email"],temple)).fetchone()["c"]
        japa_count=conn.execute("SELECT COALESCE(SUM(count),0) c FROM japa_history WHERE email=? AND temple=?",(user["email"],temple)).fetchone()["c"]
    except Exception:
        seva_count=conn.execute("SELECT COUNT(*) c FROM seva_history WHERE email=?",(user["email"],)).fetchone()["c"]; japa_count=conn.execute("SELECT COALESCE(SUM(count),0) c FROM japa_history WHERE email=?",(user["email"],)).fetchone()["c"]
    row=conn.execute("SELECT sowed_at FROM khetri WHERE email=?",(user["email"],)).fetchone(); conn.close()
    khetri_days=0
    if row and row["sowed_at"]:
        try: khetri_days=max(0,int((india_now()-datetime.fromisoformat(row["sowed_at"])).total_seconds()/86400))
        except Exception: pass
    ach=achievements_for(stats,seva_count,japa_count,khetri_days); unlocked=sum(1 for x in ach if x[2]); deity=_dual_deity_word()
    st.markdown(f"<div class='section-title'><h2>🙏 My Bhakti Dashboard</h2><span>{user['name']} • {deity} devotional journey</span></div><div class='card' style='background:linear-gradient(135deg,{TODAY_THEME['deep']},{TODAY_THEME['primary']});color:white;border:0;text-align:center;padding:28px'><div style='font-size:13px;letter-spacing:2px;font-weight:800;opacity:.85'>CURRENT BHAKTI STREAK</div><div style='font-size:54px;font-weight:900'>🔥 {stats['streak']} <span style='font-size:22px'>days</span></div><div style='opacity:.9'>Keep returning to your virtual Mandir each day.</div></div>",unsafe_allow_html=True)
    cols=st.columns(4)
    for col,(ic,val,label) in zip(cols,[("🌿" if temple_is_shiva() else "🌺",seva_count,"Seva"),("📿",japa_count,"Japa"),("🪔",stats["diyas"],"Diyas"),("🏆",f"{unlocked}/{len(ach)}","Achievements")]):
        with col: st.markdown(f"<div class='stat-card' style='text-align:center'><div style='font-size:27px'>{ic}</div><div class='stat-value'>{val}</div><div class='stat-label'>{label}</div></div>",unsafe_allow_html=True)
    st.markdown("<div class='section-title'><h2>🏆 Achievements</h2><span>Unlock milestones through devotional activity</span></div>",unsafe_allow_html=True)
    for start in range(0,len(ach),5):
        cols=st.columns(5)
        for col,(ic,name,ok) in zip(cols,ach[start:start+5]):
            with col: st.markdown(f"<div class='card' style='text-align:center;opacity:{1 if ok else .42};min-height:120px'><div style='font-size:35px'>{ic}</div><b>{name}</b><div class='small-muted'>{'Unlocked ✓' if ok else 'Locked'}</div></div>",unsafe_allow_html=True)
    st.markdown("<div class='section-title'><h2>🎁 Daily Bhakti Bonus</h2><span>One virtual bonus per IST day</span></div>",unsafe_allow_html=True)
    today=india_now().date().isoformat(); already=stats["daily_bonus_date"]==today
    if already: st.success("🌺 Today's ₹108 virtual Bhakti Bonus has already been claimed.")
    elif st.button("🎁 Claim Today's ₹108 Virtual Bonus",use_container_width=True):
        ok,bonus=claim_daily_bonus()
        if ok: st.success(f"🙏 {temple_greeting()} {format_money(bonus)} virtual credits added."); st.rerun()
    if st.button("← Home",key="back_dashboard"): go("home")

def complete_admin_panel():
    if not is_admin():
        st.error("Admin access is disabled for this account. Set ADMIN_EMAILS in Streamlit secrets/environment to your administrator email."); return
    top_header(); deity=_dual_deity_word()
    st.markdown(f"<div class='section-title'><h2>👑 Mandir Super Admin</h2><span>{deity} management, analytics and festival controls</span></div>",unsafe_allow_html=True)
    conn=db(); users=conn.execute("SELECT COUNT(*) c FROM users").fetchone()['c']; offerings=conn.execute("SELECT COUNT(*) c FROM temple_offerings").fetchone()['c']; seva_count=conn.execute("SELECT COUNT(*) c FROM seva_history").fetchone()['c']; japa=conn.execute("SELECT COALESCE(SUM(count),0) c FROM japa_history").fetchone()['c']; conn.close()
    cols=st.columns(4)
    for c,(v,l) in zip(cols,[(users,'Registered Devotees'),(offerings,'Temple Offerings'),(seva_count,'Seva Records'),(japa,'Total Japa')]):
        with c: st.metric(l,f"{v:,}")
    st.markdown("### 📣 Announcement Control")
    default_ann="Har Har Mahadev 🙏" if temple_is_shiva() else "Jai Mata Di 🙏"
    ann=st.text_area("Mandir announcement",value=st.session_state.get('admin_announcement',default_ann),key='admin_ann')
    if st.button("💾 Save Announcement",use_container_width=True):
        conn=db(); conn.execute("INSERT OR REPLACE INTO admin_settings(key,value) VALUES('announcement',?)",(ann,)); conn.commit(); conn.close(); st.success("Announcement saved.")
    st.markdown("### 🎨 Festival / Theme Control")
    c1,c2=st.columns(2)
    with c1: festival=st.text_input("Festival title",value="Shardiya Navratri 2026",key='admin_festival')
    with c2: notice=st.text_input("Special notice",value=f"{deity} Darshan is open",key='admin_notice')
    if st.button("📌 Save Festival Settings",use_container_width=True):
        conn=db(); conn.execute("INSERT OR REPLACE INTO admin_settings(key,value) VALUES('festival',?)",(festival,)); conn.execute("INSERT OR REPLACE INTO admin_settings(key,value) VALUES('notice',?)",(notice,)); conn.commit(); conn.close(); st.success("Festival settings saved.")
    st.markdown("### 📊 Recent Events")
    conn=db(); rows=conn.execute("SELECT event_type,devotee_name,created_at FROM temple_events ORDER BY id DESC LIMIT 25").fetchall(); conn.close()
    for r in rows: st.markdown(f"<div class='card' style='padding:9px;margin-bottom:5px'><b>{r['event_type']}</b> — {r['devotee_name']} <span class='small-muted'>• {r['created_at']}</span></div>",unsafe_allow_html=True)


